def check(ctx):
    d = ctx.depth()
    if d is None:
        return None
    if "ref" not in ctx.state:
        ctx.state["ref"] = d.copy()
        return None
    import math as m
    ref = ctx.state["ref"]
    diff = ref - d
    cnt = 0
    total = 0
    for row in range(0, ref.shape[0], 4):
        for col in range(0, ref.shape[1], 4):
            rv = ref[row][col]
            dv = d[row][col]
            if rv == rv and dv == dv:
                total += 1
                if abs(rv - dv) > ctx.value("change_m"):
                    cnt += 1
    ctx.state["ref"] = d.copy()
    if total > 0 and cnt > ctx.value("min_px"):
        return {"value": float(cnt), "detail": "scene depth changed at " + str(cnt) + " sampled pixels vs previous frame"}
    return None

def check(ctx):
    d = ctx.depth()
    if d is None:
        return None
    if "ref" not in ctx.state:
        ctx.state["ref"] = d.copy()
        return None
    ref = ctx.state["ref"]
    diff = np.abs(ref - d)
    valid = ~np.isnan(diff)
    cnt = int(np.sum((diff > ctx.value("change_m")) & valid))
    ctx.state["ref"] = d.copy()
    if cnt > ctx.value("min_px"):
        return {"value": float(cnt), "detail": "scene depth changed at " + str(cnt) + " pixels vs previous frame"}
    return None

